const j = $json;
const state = $getWorkflowStaticData('global');
state.attempts = state.attempts || {};

const jobName = String(j.jobName || 'unnamed job').slice(0, 80);
const key = jobName + '|' + $execution.id;
state.attempts[key] = 0;

const now = Date.now();
state.seen = (state.seen || []).filter(function (s) { return now - s.at < 86400000; });
state.seen.push({ key: key, at: now });

return [{ json: {
  jobName: jobName, key: key,
  url: String(j.url || '').trim(),
  method: String(j.method || 'GET').toUpperCase(),
  body: String(j.body || ''),
  maxAttempts: Math.min(Math.max(Number(j.maxAttempts) || 3, 1), 8),
  attempt: 1, backoffSeconds: 0,
  isReplay: false, replayOf: ''
} }];

// A dead letter register nobody replays is just a graveyard. This picks the
// ones the overnight gap may have fixed, and deliberately leaves the rest alone.
const MIN_AGE_MINUTES = 30;
const MAX_PER_SWEEP = 20;
const MAX_REPLAY_ATTEMPTS = 2;

const out = [];
const now = Date.now();
const state = $getWorkflowStaticData('global');
state.attempts = state.attempts || {};

for (const item of $input.all()) {
  if (out.length >= MAX_PER_SWEEP) break;
  const r = item.json || {};

  const status = String(r.Status || 'Open').trim().toLowerCase();
  if (status !== 'open') continue;

  // Permanent failures will fail identically forever - replaying them is waste
  const cls = String(r.Class || '').trim().toLowerCase();
  if (cls !== 'transient') continue;

  const failedAt = new Date(String(r['Failed At'] || ''));
  if (isNaN(failedAt.getTime())) continue;
  if (now - failedAt.getTime() < MIN_AGE_MINUTES * 60000) continue;

  const endpoint = String(r.Endpoint || '').trim();
  const sp = endpoint.indexOf(' ');
  if (sp === -1) continue;
  const method = endpoint.slice(0, sp).toUpperCase();
  const url = endpoint.slice(sp + 1).trim();
  if (!url) continue;

  const jobName = String(r.Job || 'replayed job').slice(0, 80);
  const key = jobName + '|replay|' + $execution.id + '|' + out.length;
  state.attempts[key] = 0;

  out.push({ json: {
    jobName: jobName, key: key, url: url, method: method,
    body: String(r.Payload || ''),
    maxAttempts: MAX_REPLAY_ATTEMPTS,
    attempt: 1, backoffSeconds: 0,
    isReplay: true, replayOf: String(r['Failed At'] || '')
  } });
}

return out;

const cfg = $('Call the Service').item.json;
let src = {};
try { src = $('Start the Attempt Counter').item.json; } catch (e) { src = {}; }
if (!src.jobName) { try { src = $('Pick What Is Worth Another Try').item.json; } catch (e2) { src = {}; } }

const state = $getWorkflowStaticData('global');
const attempts = ((state.attempts || {})[src.key] || 0) + 1;

return { json: {
  ok: true,
  jobName: src.jobName || 'unnamed job',
  attemptsUsed: attempts,
  isReplay: src.isReplay === true,
  replayOf: src.replayOf || '',
  response: cfg,
  summary: (src.jobName || 'The job') + (src.isReplay ? ' succeeded on replay' : ' succeeded') + ' on attempt ' + attempts + '.'
} };

let cfg = {};
try { cfg = $('Start the Attempt Counter').item.json; } catch (e) { cfg = {}; }
if (!cfg.jobName) { try { cfg = $('Pick What Is Worth Another Try').item.json; } catch (e2) { cfg = {}; } }

const t = $json.output || {};
const state = $getWorkflowStaticData('global');
state.attempts = state.attempts || {};
state.attempts[cfg.key] = (state.attempts[cfg.key] || 0) + 1;

const used = state.attempts[cfg.key];
const cls = ['transient', 'permanent', 'needs_human'].indexOf(t.class) === -1 ? 'needs_human' : t.class;
const attemptsLeft = (cfg.maxAttempts || 3) - used;

let verdict;
if (cls === 'transient' && t.retry_would_help === true && attemptsLeft > 0) verdict = 'retry';
else if (cls === 'transient' && attemptsLeft <= 0) verdict = 'exhausted';
else verdict = 'dead_letter';

return { json: {
  verdict: verdict, errorClass: cls,
  cause: String(t.cause || 'No diagnosis available'),
  humanAction: String(t.human_action || ''),
  backoffSeconds: Math.min(Math.max(Number(t.backoff_seconds) || 15, 5), 300),
  attemptsUsed: used, attemptsLeft: attemptsLeft < 0 ? 0 : attemptsLeft,
  jobName: cfg.jobName, key: cfg.key, url: cfg.url, method: cfg.method, body: cfg.body,
  maxAttempts: cfg.maxAttempts, attempt: used + 1,
  isReplay: cfg.isReplay === true, replayOf: cfg.replayOf || ''
} };

const d = $('Count It and Decide').item.json;
const wasExhausted = d.verdict === 'exhausted';

return { json: {
  ok: false, jobName: d.jobName, attemptsUsed: d.attemptsUsed,
  errorClass: d.errorClass, cause: d.cause, humanAction: d.humanAction,
  retryPointless: d.errorClass !== 'transient',
  wasReplay: d.isReplay === true,
  filedInRegister: true,
  summary: d.jobName + ' failed after ' + d.attemptsUsed + ' attempt(s). ' + (wasExhausted ? 'The service kept failing and the retry budget ran out. ' : (d.errorClass === 'permanent' ? 'Retrying was pointless - the request itself is being rejected. ' : 'A person needs to unblock this. ')) + d.cause + (d.humanAction ? ' Action: ' + d.humanAction : '')
} };
